+export type DurationHistory = Record<string, DurationObservation[]>
+
+function toObservations(value: unknown): DurationObservation[] | null {
+  if (typeof value === 'number' && Number.isFinite(value)) {
+    return [{ duration: value, recordedAt: 0 }]
+  }
+  const values = typeof value === 'object' && value !== null && 'observations' in value
+    ? (value as { observations: unknown }).observations
+    : [value]
+  if (!Array.isArray(values) || values.some(observation => typeof observation !== 'object' || observation === null || !Number.isFinite((observation as DurationObservation).duration) || !Number.isFinite((observation as DurationObservation).recordedAt))) {
+    return null
+  }
+  return values.map(observation => ({ duration: (observation as DurationObservation).duration, recordedAt: (observation as DurationObservation).recordedAt }))
+}
+
+export async function readDurationHistory(config: ResolvedConfig): Promise<DurationHistory | null> {
+  try {
+    const raw = JSON.parse(await fs.readFile(resolve(config.root, config.sequence.durationHistoryPath), 'utf8'))
+    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
+      return null
+    }
+    const history: DurationHistory = {}
+    for (const [path, value] of Object.entries(raw)) {
+      const observations = toObservations(value)
+      if (!observations) {
+        return null
+      }
+      history[path] = observations
+    }
+    return history
+  }
+  catch {
+    return null
+  }
+}
